-- Countries reference data (ISO 3166-1). Idempotent: safe to re-run.
-- Loaded directly into the CRM DB (not via Drizzle migrations) to avoid journal churn.

CREATE TABLE IF NOT EXISTS public.countries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    iso character varying(255) NOT NULL,
    iso3 character varying(255),
    name character varying(255) NOT NULL,
    phone_code character varying(255) NOT NULL,
    currency character varying(50),
    currency_code character varying(10),
    flag character varying(20),
    CONSTRAINT countries_pkey PRIMARY KEY (id)
);

